&=\int_{-2}^{2} \sinh{x^3}\cdot x^2\,\textrm{d}x\[5pt]
&=\int_{-8}^{8} \sinh{u}\cdot\dfrac{1}{3}\, \textrm{d}u\[5pt]
&=\dfrac{1}{3}\cosh u\Big|_{-8}^{8}\[5pt]
